import { z } from "zod";

/**
 * Line item generated by AI assistant
 */
export const aiItemSchema = z.object({
  name: z.string().min(1, "Item name is required"),
  quantity: z.number().min(1, "Quantity must be at least 1"),
  price: z.number().min(0, "Price must be non-negative"),
});

export type AiItem = z.infer<typeof aiItemSchema>;

/**
 * Structured invoice draft generated by AI from a natural language prompt
 */
export const aiInvoiceDraftSchema = z.object({
  clientName: z.string().nullish().transform((v) => v ?? ""),
  clientEmail: z.string().nullish().transform((v) => v ?? ""),
  description: z.string().nullish().transform((v) => v || "Services Rendered"),
  paymentTerms: z
    .union([z.literal(1), z.literal(7), z.literal(14), z.literal(30)])
    .or(
      z.coerce.number().transform((val) => {
        if ([1, 7, 14, 30].includes(val)) return val as 1 | 7 | 14 | 30;
        return 30 as const;
      })
    )
    .default(30),
  items: z.array(aiItemSchema).min(1, "At least one item is required"),
  // Only present when the prompt states a sender address; otherwise the form
  // falls back to the business profile.
  senderAddress: z
    .object({
      street: z.string().nullish(),
      city: z.string().nullish(),
      postCode: z.string().nullish(),
      country: z.string().nullish(),
    })
    .nullish()
    .transform((v) =>
      v && v.street && v.city && v.postCode && v.country
        ? {
            street: v.street,
            city: v.city,
            postCode: v.postCode,
            country: v.country,
          }
        : undefined
    ),
  // ISO 4217 code inferred from the prompt; undefined falls back to the default
  currency: z
    .string()
    .nullish()
    .transform((v) => {
      const code = v?.trim().toUpperCase();
      return code && /^[A-Z]{3}$/.test(code) ? code : undefined;
    }),
  clientAddress: z
    .object({
      street: z.string().nullish().transform((v) => v ?? ""),
      city: z.string().nullish().transform((v) => v ?? ""),
      postCode: z.string().nullish().transform((v) => v ?? ""),
      country: z.string().nullish().transform((v) => v ?? ""),
    })
    .nullish()
    .transform((v) => ({
      street: v?.street ?? "",
      city: v?.city ?? "",
      postCode: v?.postCode ?? "",
      country: v?.country ?? "",
    })),
  taxRate: z.coerce.number().min(0).max(100).nullish().transform((v) => v ?? 0),
  discount: z.coerce.number().min(0).nullish().transform((v) => v ?? 0),
  notes: z.string().nullish().transform((v) => v ?? ""),
});

export type AiInvoiceDraft = z.infer<typeof aiInvoiceDraftSchema>;

/**
 * Request payload sent to POST /api/ai/invoice-draft
 */
export const aiDraftRequestSchema = z.object({
  prompt: z
    .string()
    .trim()
    .min(3, "Prompt must be at least 3 characters")
    .max(2000, "Prompt cannot exceed 2000 characters"),
});

export type AiDraftRequest = z.infer<typeof aiDraftRequestSchema>;

/**
 * Payment reminder generation request schema
 */
export const aiReminderRequestSchema = z.object({
  invoiceId: z.string().min(1, "Invoice ID is required"),
  clientName: z.string().min(1, "Client name is required"),
  clientEmail: z.string().nullish().transform((v) => v || ""),
  description: z.string().nullish().transform((v) => v || "Services rendered"),
  total: z.string().or(z.number()),
  paymentDue: z.string().nullish().transform((v) => v || "Due upon receipt"),
  status: z
    .enum(["draft", "pending", "paid", "overdue", "cancelled"])
    .default("pending"),
  daysOverdue: z.number().int().min(0).default(0),
  tone: z.enum(["friendly", "firm", "urgent"]).default("friendly"),
});

export type AiReminderRequest = z.infer<typeof aiReminderRequestSchema>;

/**
 * Structured reminder email generated by AI
 */
export const aiReminderResponseSchema = z.object({
  subject: z.string().min(1, "Subject is required"),
  body: z.string().min(1, "Email body is required"),
});

export type AiReminderResponse = z.infer<typeof aiReminderResponseSchema>;

